;resize:none;background:transparent;color:#e5ede8;font:13px/22px Consolas,monospace;padding:12px 8px;white-space:pre;tab-size:2}.line-gutter{margin:0;overflow:hidden;text-align:right;padding:12px 10px;font:13px/22px Consolas,monospace;color:#788d84;min-width:42px;user-select:none}.import-button{font-size:12px;color:#38644f;cursor:pointer}.import-button input{display:none}.context-pill{font-size:12px;background:#f0f5f1;padding:10px;border-radius:6px;line-height:1.8}.action{font-size:13px;border-bottom:1px solid #e0e8e3;padding:12px 0;overflow-wrap:anywhere}.action pre{white-space:pre-wrap;max-height:240px;overflow:auto;background:#f4f6f5;padding:8px;font-size:12px}.agent-answer{white-space:pre-wrap;line-height:1.8}.user-message{background:#edf4ef;padding:10px;border-radius:6px}.agent-pane>.el-button{margin-top:10px}.diff{display:grid;grid-template-columns:1fr 1fr;gap:10px}.diff>div{min-width:0;background:#f5f7f5;padding:12px}.diff pre{white-space:pre-wrap;overflow-wrap:anywhere;font:12px/1.7 Consolas,monospace;max-height:420px;overflow:auto}@media(max-width:1450px){.studio-grid{grid-template-columns:220px minmax(300px,1fr)}.plan-pane{position:static}.agent-pane{grid-column:1/-1;position:static;max-height:none}.conversation{max-height:420px;overflow:auto}}@media(max-width:850px){.studio-grid{display:block}.studio-pane{margin-bottom:14px}.plan-pane{position:static;max-height:360px}.ide{grid-template-columns:120px minmax(0,1fr)}.reference-code,.ide{height:480px}.diff{grid-template-columns:1fr}}
</style>
